insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('f9b12aff-95dd-4946-a250-8174fbdafb4c', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', null, 'topic'::public.curated_course_node_type, 'Course Orientation, Mathematical Language, and Discrete Structures', 'This opening unit establishes the objects, notation, and habits that make discrete mathematics a precise language for computing, mathematics, and digital engineering.', 0),
  ('dd29d7b9-f25a-4b07-a56c-d7ab9e6925af', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'f9b12aff-95dd-4946-a250-8174fbdafb4c', 'subtopic'::public.curated_course_node_type, 'What Discrete Mathematics Studies', 'Students distinguish finite and countable structures from continuous models and see why discrete abstraction is central to algorithms and hardware.', 0),
  ('1a9e68fc-30ff-42a9-b239-bd8edef041a3', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'dd29d7b9-f25a-4b07-a56c-d7ab9e6925af', 'concept'::public.curated_course_node_type, 'Finite, countable, and combinatorial objects', null, 0),
  ('2ace3fa0-014d-419d-9dc5-1861c97f113e', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'dd29d7b9-f25a-4b07-a56c-d7ab9e6925af', 'concept'::public.curated_course_node_type, 'Examples from programs, networks, circuits, and proofs', null, 1),
  ('17bd1f31-f1c1-4fa4-8d5a-5a65ef2c09b0', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'dd29d7b9-f25a-4b07-a56c-d7ab9e6925af', 'concept'::public.curated_course_node_type, 'Abstraction from a real system to a mathematical model', null, 2),
  ('a101833b-f112-4a6a-97b4-eb324abcdcfb', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'f9b12aff-95dd-4946-a250-8174fbdafb4c', 'subtopic'::public.curated_course_node_type, 'Definitions, Statements, and Notation', 'Precise definitions control what may be assumed and what must be proved. Notation makes those commitments compact and checkable.', 1),
  ('86190624-db1f-405f-b32d-de4c334dcdda', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'a101833b-f112-4a6a-97b4-eb324abcdcfb', 'concept'::public.curated_course_node_type, 'Objects, variables, domains, and types', null, 0),
