  ('c369a87a-52d0-40bf-b0d6-2be7ce6b856a', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'a101833b-f112-4a6a-97b4-eb324abcdcfb', 'concept'::public.curated_course_node_type, 'Set, sequence, summation, and logical notation', null, 2),
  ('aaec66c0-6db9-4fbb-9607-7645b9a5f71f', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'f9b12aff-95dd-4946-a250-8174fbdafb4c', 'subtopic'::public.curated_course_node_type, 'Problem-Solving and Computational Exploration', 'Good discrete problem solving alternates examples, conjectures, proof, and computation without confusing experimental evidence with proof.', 2),
  ('2289c0e5-b895-4c5b-9363-704798f3fb29', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'aaec66c0-6db9-4fbb-9607-7645b9a5f71f', 'concept'::public.curated_course_node_type, 'Small cases and pattern discovery', null, 0),
  ('cee32da9-b932-4e6e-b00f-c0b8dc291495', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'aaec66c0-6db9-4fbb-9607-7645b9a5f71f', 'concept'::public.curated_course_node_type, 'Conjectures, counterexamples, and refinement', null, 1),
  ('96a79fbd-c194-40f2-a2a8-f1fb172cb2b9', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'aaec66c0-6db9-4fbb-9607-7645b9a5f71f', 'concept'::public.curated_course_node_type, 'Python or SageMath checks with reproducible reasoning', null, 2),
  ('0b012c27-5afc-49cd-9be7-274266f2bbf1', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', null, 'topic'::public.curated_course_node_type, 'Propositional Logic and Logical Equivalence', 'Propositional logic supplies a formal language for combining claims and deciding when an argument, specification, or circuit is valid.', 1),
  ('fe4af8a7-8a6e-4394-bb7e-b423dbf30542', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '0b012c27-5afc-49cd-9be7-274266f2bbf1', 'subtopic'::public.curated_course_node_type, 'Propositions and Connectives', 'Students translate ordinary statements into formulas whose truth depends on well-defined logical operations.', 0),
  ('e7f2410e-62cf-42db-92f8-507ab348aa62', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'fe4af8a7-8a6e-4394-bb7e-b423dbf30542', 'concept'::public.curated_course_node_type, 'Negation, conjunction, disjunction, implication, and biconditional', null, 0),
  ('7fadd469-5359-4c28-ae7a-efa436e5f4c8', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'fe4af8a7-8a6e-4394-bb7e-b423dbf30542', 'concept'::public.curated_course_node_type, 'Operator precedence and parenthesization', null, 1),
  ('f8196385-04d1-4169-a717-5d8b9a8873f7', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'fe4af8a7-8a6e-4394-bb7e-b423dbf30542', 'concept'::public.curated_course_node_type, 'Necessary and sufficient conditions', null, 2),
  ('4c91478d-1f5f-431a-ac7b-2958d57094e4', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '0b012c27-5afc-49cd-9be7-274266f2bbf1', 'subtopic'::public.curated_course_node_type, 'Truth Tables and Equivalence', 'Truth tables expose the behavior of compound statements and support systematic simplification.', 1),
  ('fd405e10-86c0-4a7b-a886-fbb26f3950ae', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '4c91478d-1f5f-431a-ac7b-2958d57094e4', 'concept'::public.curated_course_node_type, 'Tautologies, contradictions, and contingencies', null, 0),
