  ('2c9105e2-e63b-4fee-a9b6-2077a3e000f1', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '4c91478d-1f5f-431a-ac7b-2958d57094e4', 'concept'::public.curated_course_node_type, 'Normal forms: CNF and DNF', null, 2),
  ('eca8be61-b8a2-4b2e-8515-aca77e311a2c', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '0b012c27-5afc-49cd-9be7-274266f2bbf1', 'subtopic'::public.curated_course_node_type, 'Inference, Satisfiability, and Applications', 'Rules of inference turn accepted premises into justified conclusions and connect logic to verification and SAT solving.', 2),
  ('fd0b2ddc-4afb-4d4e-904a-ca8ee3112936', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'eca8be61-b8a2-4b2e-8515-aca77e311a2c', 'concept'::public.curated_course_node_type, 'Validity, sound inference rules, and fallacies', null, 0),
  ('652b8aff-5d2f-4827-81c2-d145c9c6c9e4', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'eca8be61-b8a2-4b2e-8515-aca77e311a2c', 'concept'::public.curated_course_node_type, 'Satisfiability and model finding', null, 1),
  ('ab6b3d80-8ec1-4953-b186-68baf4d2d5a7', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'eca8be61-b8a2-4b2e-8515-aca77e311a2c', 'concept'::public.curated_course_node_type, 'Specifications, assertions, and combinational logic', null, 2),
  ('7b09568b-eb26-4a98-a60d-872a6691a1ff', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', null, 'topic'::public.curated_course_node_type, 'Predicate Logic, Quantifiers, and Formal Inference', 'Predicate logic extends propositional reasoning to properties of objects, making it possible to express mathematical definitions and program specifications accurately.', 2),
  ('1fea4544-7192-459a-914b-c52f1ca2953c', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '7b09568b-eb26-4a98-a60d-872a6691a1ff', 'subtopic'::public.curated_course_node_type, 'Predicates, Domains, and Free Variables', 'A predicate becomes meaningful only relative to its variables and domain, so students learn to make both explicit.', 0),
  ('b8b1107f-4dad-45aa-97e9-6dac96041d4e', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '1fea4544-7192-459a-914b-c52f1ca2953c', 'concept'::public.curated_course_node_type, 'Predicates and propositional functions', null, 0),
  ('d3e2abaa-c9b7-464b-9502-6b4c166ccbc5', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '1fea4544-7192-459a-914b-c52f1ca2953c', 'concept'::public.curated_course_node_type, 'Free and bound variables', null, 1),
  ('e337531e-f165-4822-b4bf-70735f5fc6c2', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '1fea4544-7192-459a-914b-c52f1ca2953c', 'concept'::public.curated_course_node_type, 'Domain dependence and typed statements', null, 2),
  ('ef4da824-a519-4fed-af41-9bca5f386f2a', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '7b09568b-eb26-4a98-a60d-872a6691a1ff', 'subtopic'::public.curated_course_node_type, 'Quantifiers and Negation', 'Universal and existential quantifiers express scope. Careful negation prevents common errors in proofs and specifications.', 1),
  ('252a9f5d-69d9-4e04-ac3b-cecdeecf2926', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'ef4da824-a519-4fed-af41-9bca5f386f2a', 'concept'::public.curated_course_node_type, 'Universal and existential quantification', null, 0),
  ('2faa1389-d523-4116-a8c7-6e8dc9af97f0', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'ef4da824-a519-4fed-af41-9bca5f386f2a', 'concept'::public.curated_course_node_type, 'Nested quantifiers and order sensitivity', null, 1),
  ('b640f9b4-3a04-4aa6-8d9a-9b0c0e2a708a', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'ef4da824-a519-4fed-af41-9bca5f386f2a', 'concept'::public.curated_course_node_type, 'Negating quantified statements', null, 2),
  ('15ff3586-f609-4832-bd6b-bb655a948d4c', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '7b09568b-eb26-4a98-a60d-872a6691a1ff', 'subtopic'::public.curated_course_node_type, 'Formal Inference and Specification', 'Quantified inference supports theorem proving, database queries, contracts, and requirements.', 2),
  ('e4b594ce-fd2b-4d6a-9cfc-eb2ea6f3ae05', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '15ff3586-f609-4832-bd6b-bb655a948d4c', 'concept'::public.curated_course_node_type, 'Universal instantiation and generalization', null, 0),
  ('a1a9aab6-9cb6-44e1-a5f0-d8d471833c0c', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '15ff3586-f609-4832-bd6b-bb655a948d4c', 'concept'::public.curated_course_node_type, 'Existential instantiation and proof obligations', null, 1),
  ('3113a4ee-ec82-4384-87a8-62c1f3e68faa', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '15ff3586-f609-4832-bd6b-bb655a948d4c', 'concept'::public.curated_course_node_type, 'Translating requirements into first-order statements', null, 2),
  ('7419feb7-49d4-4ee9-b055-d7742a6bce58', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', null, 'topic'::public.curated_course_node_type, 'Sets, Functions, Relations, and Cardinality', 'Sets, functions, relations, and cardinality describe collections and mappings, the structural vocabulary behind data types, databases, graphs, and modern mathematics.', 3),
  ('d5cceda7-3e9e-477d-986b-3a7e0db97619', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '7419feb7-49d4-4ee9-b055-d7742a6bce58', 'subtopic'::public.curated_course_node_type, 'Sets and Set Operations', 'Students use sets to represent collections and manipulate them with identities that parallel logic.', 0),
  ('da344821-7edb-4093-81a9-c88c56c4bbd0', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'd5cceda7-3e9e-477d-986b-3a7e0db97619', 'concept'::public.curated_course_node_type, 'Membership, subsets, power sets, and products', null, 0),
