  ('ea7ae656-da66-449e-82ed-8ccccd8116a6', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'd5cceda7-3e9e-477d-986b-3a7e0db97619', 'concept'::public.curated_course_node_type, 'Set identities and Venn-diagram reasoning', null, 2),
  ('ff626150-c25a-4197-afea-fb1bef7175da', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '7419feb7-49d4-4ee9-b055-d7742a6bce58', 'subtopic'::public.curated_course_node_type, 'Functions and Mappings', 'Functions formalize deterministic input-output behavior and support counting, equivalence, and algorithm design.', 1),
  ('971dba67-76ca-4c1c-afd8-cf955ea479ac', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'ff626150-c25a-4197-afea-fb1bef7175da', 'concept'::public.curated_course_node_type, 'Domain, codomain, image, and preimage', null, 0),
