  ('baeb7fda-9f7f-47c5-bd5a-73e51aae974b', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'ff626150-c25a-4197-afea-fb1bef7175da', 'concept'::public.curated_course_node_type, 'Composition, inverses, and pigeonhole reasoning', null, 2),
  ('58d118b1-3977-4fb8-8f05-4d7658e6fb15', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '7419feb7-49d4-4ee9-b055-d7742a6bce58', 'subtopic'::public.curated_course_node_type, 'Relations and Cardinality', 'Relations organize objects by similarity or order, while cardinality compares the sizes of finite and infinite sets.', 2),
  ('b590f92c-90dc-4177-b103-718f5079cdc6', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '58d118b1-3977-4fb8-8f05-4d7658e6fb15', 'concept'::public.curated_course_node_type, 'Equivalence relations and partitions', null, 0),
  ('fc3eaa8f-ac37-4753-afbe-d54c238c31a7', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '58d118b1-3977-4fb8-8f05-4d7658e6fb15', 'concept'::public.curated_course_node_type, 'Partial orders, Hasse diagrams, and closures', null, 1),
  ('f2297cf4-6f07-4c98-a682-435e5d0168eb', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '58d118b1-3977-4fb8-8f05-4d7658e6fb15', 'concept'::public.curated_course_node_type, 'Finite, countably infinite, and uncountable sets', null, 2),
  ('b5b98916-4c9b-4fc3-9e9b-f4f3ea307f1d', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', null, 'topic'::public.curated_course_node_type, 'Proof Techniques and Mathematical Writing', 'Proof is the course''s central practice: it converts plausible patterns into conclusions that remain correct for every permitted case.', 4),
  ('4f736c1a-b6fa-49ef-b00e-dcbbd3e3cd7d', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'b5b98916-4c9b-4fc3-9e9b-f4f3ea307f1d', 'subtopic'::public.curated_course_node_type, 'Direct Proof, Cases, and Existence', 'Students learn constructive proof patterns that follow definitions and expose why a statement is true.', 0),
  ('b4d0c92a-2467-408e-a477-bf63a7eb8cb3', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '4f736c1a-b6fa-49ef-b00e-dcbbd3e3cd7d', 'concept'::public.curated_course_node_type, 'Direct implication proofs', null, 0),
  ('314528b4-a4b3-41f8-8789-46f0a454db4e', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '4f736c1a-b6fa-49ef-b00e-dcbbd3e3cd7d', 'concept'::public.curated_course_node_type, 'Exhaustive proof by cases', null, 1),
  ('0a92258e-dc6a-47e9-bfc4-7ff4810ebcda', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '4f736c1a-b6fa-49ef-b00e-dcbbd3e3cd7d', 'concept'::public.curated_course_node_type, 'Constructive and nonconstructive existence', null, 2),
  ('3959180a-5ecd-4c34-b1e5-3e8e0fea5fbb', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'b5b98916-4c9b-4fc3-9e9b-f4f3ea307f1d', 'subtopic'::public.curated_course_node_type, 'Contrapositive, Contradiction, and Counterexample', 'Indirect methods simplify difficult implications, while one valid counterexample defeats a universal claim.', 1),
  ('d9892341-08c4-488b-97fa-bdd116a25345', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '3959180a-5ecd-4c34-b1e5-3e8e0fea5fbb', 'concept'::public.curated_course_node_type, 'Proof by contrapositive', null, 0),
  ('325114a4-be27-4e45-aa26-f763d3b01d88', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '3959180a-5ecd-4c34-b1e5-3e8e0fea5fbb', 'concept'::public.curated_course_node_type, 'Proof by contradiction', null, 1),
  ('6eb849cf-df69-4c31-94e5-82e4251ac3c8', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '3959180a-5ecd-4c34-b1e5-3e8e0fea5fbb', 'concept'::public.curated_course_node_type, 'Disproving statements with counterexamples', null, 2),
  ('8fc97679-334f-462c-b9e1-616705e6fbdd', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'b5b98916-4c9b-4fc3-9e9b-f4f3ea307f1d', 'subtopic'::public.curated_course_node_type, 'Mathematical Writing and Proof Review', 'A proof must be logically complete and readable by another person, not merely convincing to its author.', 2),
  ('e76db124-abeb-4993-9e03-089e09853994', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '8fc97679-334f-462c-b9e1-616705e6fbdd', 'concept'::public.curated_course_node_type, 'Definitions cited at the point of use', null, 0),
  ('eb99781b-6dbc-4e20-bf01-82fedf3ac1b2', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '8fc97679-334f-462c-b9e1-616705e6fbdd', 'concept'::public.curated_course_node_type, 'Clear variable scope and quantified claims', null, 1),
  ('641f66de-d229-451c-bce6-40d59970a415', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '8fc97679-334f-462c-b9e1-616705e6fbdd', 'concept'::public.curated_course_node_type, 'Proof critique, revision, and LaTeX conventions', null, 2),
  ('3afc921d-1364-4ea7-85d3-bac7177baa4e', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', null, 'topic'::public.curated_course_node_type, 'Mathematical Induction, Recursion, and Invariants', 'Induction and invariants reason about recursively generated objects and processes that evolve through repeated steps.', 5),
  ('65d85c4e-5ebb-478f-84c9-15c0f9e5ff12', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '3afc921d-1364-4ea7-85d3-bac7177baa4e', 'subtopic'::public.curated_course_node_type, 'Ordinary and Strong Induction', 'Induction proves an infinite family of statements by connecting each case to established earlier cases.', 0),
  ('aa407ef3-3b25-48e4-9d75-b5ad7a996b26', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '65d85c4e-5ebb-478f-84c9-15c0f9e5ff12', 'concept'::public.curated_course_node_type, 'Base cases and inductive hypotheses', null, 0),
