  ('6f1b32ca-4162-43be-a1dc-27fc86b53871', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '24d8fc1c-3bcf-4ad1-81bd-1b7b35cb1c29', 'subtopic'::public.curated_course_node_type, 'Planarity, Coloring, and Graph Invariants', 'Structural invariants bound what a graph can represent and support scheduling, layout, and resource allocation.', 2),
  ('d92b2e85-b007-4e40-91a3-c9cd466d9a30', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '6f1b32ca-4162-43be-a1dc-27fc86b53871', 'concept'::public.curated_course_node_type, 'Planar embeddings and Euler''s formula', null, 0),
