  ('5abd9874-802d-4b64-bf64-e497d09849c5', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '6f1b32ca-4162-43be-a1dc-27fc86b53871', 'concept'::public.curated_course_node_type, 'Cliques, independent sets, and chromatic bounds', null, 2),
  ('e32b661a-462c-4b51-89da-d39bae9773d5', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', null, 'topic'::public.curated_course_node_type, 'Trees, Matchings, Network Algorithms, and Discrete Optimization', 'This unit turns graph structure into algorithms for hierarchy, routing, assignment, and optimization.', 11),
  ('c2b807e0-6575-49d5-9742-24fe1359b1d8', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'e32b661a-462c-4b51-89da-d39bae9773d5', 'subtopic'::public.curated_course_node_type, 'Trees and Spanning Trees', 'Trees are minimally connected graphs and the natural structure for hierarchy, recursion, and network backbones.', 0),
  ('ee543189-1539-4804-9171-aa7c7bc9ae3c', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'c2b807e0-6575-49d5-9742-24fe1359b1d8', 'concept'::public.curated_course_node_type, 'Rooted trees, traversals, and binary trees', null, 0),
