  ('18f0872f-6c34-43ba-99cc-7c5d06e5f266', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'e32b661a-462c-4b51-89da-d39bae9773d5', 'subtopic'::public.curated_course_node_type, 'Traversal and Shortest-Path Algorithms', 'Systematic traversal discovers structure, while shortest-path methods optimize movement through weighted networks.', 1),
  ('830a0a0a-87f2-4e4b-841e-c00a171138b6', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '18f0872f-6c34-43ba-99cc-7c5d06e5f266', 'concept'::public.curated_course_node_type, 'Breadth-first and depth-first search', null, 0),
