  ('e6bd079e-6781-4181-969a-ca32bdaee106', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'b474f801-a616-4998-8925-a75aa96134af', 'concept'::public.curated_course_node_type, 'Bipartite matching and augmenting paths', null, 0),
