  ('ecb22507-8bb8-42f6-988f-09e772c057d4', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', null, 'topic'::public.curated_course_node_type, 'Boolean Algebra, Digital Logic, and Computation Structures', 'Boolean algebra connects logical reasoning to the design, simplification, and verification of digital systems.', 12),
  ('514a3dff-eb56-46b9-8383-5af2b78669f5', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'ecb22507-8bb8-42f6-988f-09e772c057d4', 'subtopic'::public.curated_course_node_type, 'Boolean Operations and Laws', 'Boolean algebra gives symbolic rules for manipulating two-valued functions.', 0),
  ('ecfcd00b-c680-4675-b4e8-a1210ae9aa58', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '514a3dff-eb56-46b9-8383-5af2b78669f5', 'concept'::public.curated_course_node_type, 'Identity, complement, distributive, and De Morgan laws', null, 0),
