  ('4f2bc328-42aa-476b-bda9-c03810496ee9', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'ecb22507-8bb8-42f6-988f-09e772c057d4', 'subtopic'::public.curated_course_node_type, 'Normal Forms and Combinational Circuits', 'Canonical forms translate directly between specifications and gate-level implementations.', 1),
  ('3f7e6af4-0daa-4839-858b-64495039a0cc', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '4f2bc328-42aa-476b-bda9-c03810496ee9', 'concept'::public.curated_course_node_type, 'Sum-of-products and product-of-sums', null, 0),
