  ('a2320b48-e362-40ab-927d-d112309a942a', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '4f2bc328-42aa-476b-bda9-c03810496ee9', 'concept'::public.curated_course_node_type, 'Logic gates, multiplexers, decoders, and adders', null, 2),
  ('95ce5694-d1b0-4496-a344-eb4db0978a58', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'ecb22507-8bb8-42f6-988f-09e772c057d4', 'subtopic'::public.curated_course_node_type, 'Sequential Logic and Computation Structures', 'State and time turn combinational logic into machines that store information and execute protocols.', 2),
  ('0baf429b-e841-437e-b147-e0c9f421b8fa', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '95ce5694-d1b0-4496-a344-eb4db0978a58', 'concept'::public.curated_course_node_type, 'Latches, flip-flops, registers, and counters', null, 0),
