  ('25734ca8-6541-41e3-a3d7-19f6971a45d3', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '95ce5694-d1b0-4496-a344-eb4db0978a58', 'concept'::public.curated_course_node_type, 'Hazards, timing assumptions, and hardware verification', null, 2),
  ('ebaade3c-3cb1-4149-9c51-b87809b05c9f', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', null, 'topic'::public.curated_course_node_type, 'Finite Automata, Regular Languages, and Parsing Foundations', 'Automata and formal languages make computation itself a mathematical object, linking software patterns to hardware state machines.', 13),
  ('d73decb6-297e-4d0d-88ae-dd6942abdc7a', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'ebaade3c-3cb1-4149-9c51-b87809b05c9f', 'subtopic'::public.curated_course_node_type, 'Deterministic and Nondeterministic Automata', 'Finite automata recognize patterns using bounded memory. Nondeterminism offers an equivalent but often simpler description.', 0),
  ('46521d03-2772-4cf2-aaaf-1f7d824c51d4', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'd73decb6-297e-4d0d-88ae-dd6942abdc7a', 'concept'::public.curated_course_node_type, 'DFAs, transition functions, and accepted languages', null, 0),
  ('72e429d5-a43b-437f-b6a9-f3089624fca8', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'd73decb6-297e-4d0d-88ae-dd6942abdc7a', 'concept'::public.curated_course_node_type, 'NFAs and subset construction', null, 1),
  ('03951ef6-1057-45f7-a1fb-bdfdf6bb13df', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'd73decb6-297e-4d0d-88ae-dd6942abdc7a', 'concept'::public.curated_course_node_type, 'Product constructions and closure operations', null, 2),
  ('8b7d5089-eb80-49c5-a688-5112b6948e4b', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'ebaade3c-3cb1-4149-9c51-b87809b05c9f', 'subtopic'::public.curated_course_node_type, 'Regular Expressions and Limits of Regularity', 'Regular expressions and automata describe the same language class, while nonregularity results expose finite-memory limits.', 1),
  ('1b594a8e-7971-4cc7-a31b-9fc3df6670bf', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '8b7d5089-eb80-49c5-a688-5112b6948e4b', 'concept'::public.curated_course_node_type, 'Regular expressions and state elimination', null, 0),
  ('33010226-15a1-453a-9568-0ec7311b0fe2', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '8b7d5089-eb80-49c5-a688-5112b6948e4b', 'concept'::public.curated_course_node_type, 'Closure properties of regular languages', null, 1),
  ('32ddf688-c1c5-4f78-9b31-1c8fd1cc23d1', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '8b7d5089-eb80-49c5-a688-5112b6948e4b', 'concept'::public.curated_course_node_type, 'Pumping lemma and Myhill-Nerode preview', null, 2),
  ('ed0a0512-478c-41d1-a1ee-edbcc8557cc6', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'ebaade3c-3cb1-4149-9c51-b87809b05c9f', 'subtopic'::public.curated_course_node_type, 'Context-Free Grammars and Parsing Foundations', 'Grammars describe nested syntax that finite automata cannot capture, providing a bridge to compilers and protocol formats.', 2),
  ('7405b5da-1935-424f-8fa4-538032f18f11', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'ed0a0512-478c-41d1-a1ee-edbcc8557cc6', 'concept'::public.curated_course_node_type, 'Productions, derivations, and parse trees', null, 0),
  ('24ef1fee-43ad-4214-8182-eb4e0d8d5852', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'ed0a0512-478c-41d1-a1ee-edbcc8557cc6', 'concept'::public.curated_course_node_type, 'Ambiguity and grammar design', null, 1),
  ('3e928ef8-252a-493c-96e3-507989252c95', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'ed0a0512-478c-41d1-a1ee-edbcc8557cc6', 'concept'::public.curated_course_node_type, 'Pushdown-automaton and parsing overview', null, 2),
  ('41040632-5a11-470b-9a2d-9b4a26aef961', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', null, 'topic'::public.curated_course_node_type, 'Countability, Computability, and Decidability', 'Countability and computability establish fundamental limits: some sets cannot be enumerated and some precisely stated problems cannot be solved by any algorithm.', 14),
  ('fb913a69-4930-4578-bbfa-610f9ec2f591', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '41040632-5a11-470b-9a2d-9b4a26aef961', 'subtopic'::public.curated_course_node_type, 'Countability and Diagonalization', 'Students compare infinite sizes and learn how diagonal arguments prove that no enumeration can be complete.', 0),
  ('b30066e4-6814-4a3a-b77f-30e85d8122bf', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'fb913a69-4930-4578-bbfa-610f9ec2f591', 'concept'::public.curated_course_node_type, 'Countable unions and encodings', null, 0),
