  ('e0205862-6bf5-4df7-b0f7-b75e76486763', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '41040632-5a11-470b-9a2d-9b4a26aef961', 'subtopic'::public.curated_course_node_type, 'Turing Machines and Encodings', 'A simple universal machine model clarifies what counts as an effective procedure.', 1),
  ('e29e02e9-2895-44f4-8a54-fe8a380c9d64', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'e0205862-6bf5-4df7-b0f7-b75e76486763', 'concept'::public.curated_course_node_type, 'Machine configurations and computation histories', null, 0),
