  ('cd333cfe-d18e-4069-81aa-0f6c512054e7', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '3bb9a3e2-55b4-44e5-82f7-f0d9f03353c9', 'concept'::public.curated_course_node_type, 'Halting problem and self-reference', null, 0),
  ('70c33bd8-7e5e-47a5-8e2e-d2392f9abdd0', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '3bb9a3e2-55b4-44e5-82f7-f0d9f03353c9', 'concept'::public.curated_course_node_type, 'Mapping reductions', null, 1),
  ('61deb3e6-b5fc-4ee4-bb5b-0274b252761f', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '3bb9a3e2-55b4-44e5-82f7-f0d9f03353c9', 'concept'::public.curated_course_node_type, 'Recognizability, co-recognizability, and limits of verification', null, 2),
  ('6ef63cf7-5861-44a3-98de-f95b96134899', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', null, 'topic'::public.curated_course_node_type, 'Algorithm Correctness, Complexity, Reductions, and Integrated Applications', 'The closing unit integrates proof, structure, and computation to distinguish correct algorithms from efficient ones and to communicate what remains infeasible or unknown.', 15),
  ('f8f2edc9-0676-405f-96d9-df9708cad941', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '6ef63cf7-5861-44a3-98de-f95b96134899', 'subtopic'::public.curated_course_node_type, 'Correctness and Resource Models', 'Students connect preconditions, invariants, postconditions, and termination to explicit measures of time and space.', 0),
  ('36f49827-ccb8-420b-9794-b128a72b7353', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'f8f2edc9-0676-405f-96d9-df9708cad941', 'concept'::public.curated_course_node_type, 'Partial and total correctness', null, 0),
  ('dc4e84ba-b0c8-4f29-88ca-62569fe16290', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'f8f2edc9-0676-405f-96d9-df9708cad941', 'concept'::public.curated_course_node_type, 'Worst-case, average-case, and amortized perspectives', null, 1),
  ('fea2bba5-ee56-4057-b99f-c3c79d57339a', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'f8f2edc9-0676-405f-96d9-df9708cad941', 'concept'::public.curated_course_node_type, 'Reasonable machine models and input size', null, 2),
  ('d34098f3-567e-4c28-a9cd-0a16f24f25af', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', '6ef63cf7-5861-44a3-98de-f95b96134899', 'subtopic'::public.curated_course_node_type, 'Complexity Classes and Reductions', 'Complexity theory groups problems by required resources and uses reductions to compare their difficulty.', 1),
  ('88243d6b-2546-4b4a-8b39-bc33d95f4c1b', '531857f0-bbfb-4884-8a67-ced2fcf87fc3', 'd34098f3-567e-4c28-a9cd-0a16f24f25af', 'concept'::public.curated_course_node_type, 'P, NP, verifiers, and certificates', null, 0),
